def main_solution(operations):
    map_ = {}
    for op in operations:
        action = op['action']
        key = op['key']
        value = op.get('value', '')

        if action == 'add':
            map_[key] = value
        elif action == 'delete':
            del map_[key]
        elif action == 'modify':
            map_[key] = value
    return {'result': map_}
